<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';import * as T from 'three';import {OrbitControls} from 'three/addons/controls/OrbitControls.js';import {RoomEnvironment} from 'three/addons/environments/RoomEnvironment.js';import {createReliefGeometries,parseMotifSvg} from '../three/motifGeometry.js';
const names:Record<string,string>={pot:'紫砂壶',tray:'茶承',bookmark:'书签',box:'圆形首饰盒',vase:'花器',pendant:'挂坠',lid:'茶罐盖',cup:'茶杯',penholder:'笔筒',incense:'香插',jar:'茶叶罐',plaque:'案头摆牌'};
function readPreference(key:string){try{return localStorage.getItem(key)}catch{return null}}
