const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const interacting=ref(false),resuming=ref(false);let resumeTimer:ReturnType<typeof setTimeout>;
const props=withDefaults(defineProps<{svg:string;vessel?:string;hero?:boolean;formation?:number;shape?:string}>(),{shape:'standard',formation:1,vessel:'pot',hero:false});const host=ref<HTMLDivElement>(),failed=ref(false),rotate=ref(!reduced&&readPreference('xiyu-auto-rotate')!=='paused'),exploded=ref(false),finish=ref(readPreference('xiyu-finish')||'brushed'),material=ref(readPreference('xiyu-material')||'zisha'),hotspot=ref('');let renderer:T.WebGLRenderer,scene:T.Scene,camera:T.PerspectiveCamera,controls:OrbitControls,group:T.Group,frame=0,observer:ResizeObserver,environment:T.Texture;let objects:T.Object3D[]=[];let pending=false;function dispose(){group?.traverse((o:any)=>{o.geometry?.dispose();const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach((m:any)=>{if(m){m.map?.dispose();m.roughnessMap?.dispose();m.dispose()}})});if(group)scene.remove(group)}
function build(){if(!scene)return;dispose();let bodyProfile:T.Vector2[]=[];group=new T.Group();scene.add(group);objects=[];const clay=new T.MeshStandardMaterial({color:material.value==='zisha'?0x50352d:material.value==='ink'?0x243331:0xded8c7,roughness:.68,metalness:.06});const silver=new T.MeshStandardMaterial({color:finish.value==='gold'?0xc6a268:0xd4dfdb,metalness:.95,roughness:finish.value==='polished'?.17:.38,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1});
const add=(geo:T.BufferGeometry,mat:T.Material,x=0,y=0,z=0)=>{const mesh=new T.Mesh(geo,mat);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return mesh};
if(props.vessel==='pot'){
 const pts=[[0,-.94],[.55,-.94],[.87,-.84],[1.01,-.52],[1.04,.03],[.96,.55],[.77,.76],[.67,.8]].map(([x,y])=>new T.Vector2(x,y));bodyProfile=new T.SplineCurve(pts).getPoints(90);add(new T.LatheGeometry(bodyProfile,128),clay);
 const lid=new T.Group();lid.position.y=exploded.value?1.4:0;group.add(lid);const lidMesh=new T.Mesh(new T.LatheGeometry([new T.Vector2(0,.89),new T.Vector2(.55,.89),new T.Vector2(.75,.82),new T.Vector2(.76,.79)],96),clay);lid.add(lidMesh);const knob=new T.Mesh(new T.SphereGeometry(.14,40,24),clay);knob.scale.set(1,.65,1);knob.position.y=.99;lid.add(knob);lidMesh.castShadow=true;
 const handleCurve=new T.CatmullRomCurve3([new T.Vector3(.85,.5,0),new T.Vector3(1.38,.56,0),new T.Vector3(1.66,.2,0),new T.Vector3(1.56,-.3,0),new T.Vector3(.94,-.56,0)]);add(new T.TubeGeometry(handleCurve,64,.105,20,false),clay);
 const spoutCurve=new T.CatmullRomCurve3([new T.Vector3(-.82,-.25,0),new T.Vector3(-1.15,-.06,0),new T.Vector3(-1.39,.22,0),new T.Vector3(-1.56,.51,0)]);const spoutGeo=new T.TubeGeometry(spoutCurve,48,.16,24,false);const pa=spoutGeo.attributes.position;for(let i=0;i<pa.count;i++){const t=Math.floor(i/25)/48,center=spoutCurve.getPointAt(Math.min(t,1));const radius=1.65-t*.9;pa.setXYZ(i,center.x+(pa.getX(i)-center.x)*radius,center.y+(pa.getY(i)-center.y)*radius,center.z+(pa.getZ(i)-center.z)*radius)}spoutGeo.computeVertexNormals();add(spoutGeo,clay);
 const lip=add(new T.TorusGeometry(.12,.025,12,40),clay,-1.56,.51);lip.rotation.y=-Math.PI/2;lip.rotation.x=-.4;
 const ring=add(new T.TorusGeometry(.66,.009,10,96),silver,0,.805);ring.rotation.x=Math.PI/2;
 }else if(props.vessel==='vase'){const pts=[[0,-1.2],[.55,-1.2],[.95,-.7],[1,-.1],[.72,.6],[.36,1.05],[.4,1.3]].map(([x,y])=>new T.Vector2(x,y));bodyProfile=new T.SplineCurve(pts).getPoints(80);add(new T.LatheGeometry(bodyProfile,96),clay);const lip=add(new T.TorusGeometry(.4,.025,12,64),silver,0,1.3);lip.rotation.x=Math.PI/2;
 }else if(['cup','penholder','jar'].includes(props.vessel)){
 const outlines:Record<string,number[][]>={cup:[[0,-.76],[.52,-.76],[.62,-.67],[.77,.55],[.81,.75]],penholder:[[0,-1.16],[.76,-1.16],[.85,-1.05],[.87,1.05]],jar:[[0,-1.1],[.69,-1.1],[.87,-.98],[.96,-.7],[.96,.55],[.78,.82],[.74,.86]]};
 const inner:Record<string,number[][]>={cup:[[.74,.75],[.71,.55],[.55,-.61],[0,-.61]],penholder:[[.78,1.05],[.76,-1],[0,-1]],jar:[[.67,.86],[.69,.7],[.85,.5],[.85,-.89],[0,-.89]]};
 const points=outlines[props.vessel];bodyProfile=points.map(([x,y])=>new T.Vector2(x,y));add(new T.LatheGeometry([...points,...inner[props.vessel]].map(([x,y])=>new T.Vector2(x,y)),112),clay);
 const top=points[points.length-1];const rim=add(new T.TorusGeometry(top[0]-.015,.018,12,96),silver,0,top[1]);rim.rotation.x=Math.PI/2;
 const foot=add(new T.TorusGeometry(props.vessel==='cup'?.52:.73,.022,12,96),silver,0,points[0][1]+.03);foot.rotation.x=Math.PI/2;
 if(props.vessel==='jar'){const lidY=exploded.value?1.8:.94;const lid=add(new T.CylinderGeometry(.79,.77,.12,96),clay,0,lidY);const knob=add(new T.SphereGeometry(.115,32,20),clay,0,lidY+.16);knob.scale.y=.6;const band=add(new T.TorusGeometry(.77,.018,12,96),silver,0,lidY+.07);band.rotation.x=Math.PI/2;lid.castShadow=true;}
 }else if(props.vessel==='incense'){
 add(new T.CylinderGeometry(1.27,1.17,.17,112),clay,0,-.8,0);const edge=add(new T.TorusGeometry(1.24,.023,12,96),silver,0,-.7,0);edge.rotation.x=Math.PI/2;
 const socket=add(new T.CylinderGeometry(.085,.11,.07,32),silver,.45,-.68,-.45);const stick=new T.CatmullRomCurve3([new T.Vector3(.45,-.64,-.45),new T.Vector3(.8,1.38,-.55)]);add(new T.TubeGeometry(stick,24,.019,8,false),new T.MeshStandardMaterial({color:0x9b6941,roughness:.85}));
 add(new T.SphereGeometry(.025,12,10),new T.MeshStandardMaterial({color:0x71685d,roughness:1}),.8,1.39,-.55);socket.castShadow=true;
 }else if(props.vessel==='plaque'){
 const plaque=new T.Shape();plaque.moveTo(-.94,-1.1);plaque.lineTo(.94,-1.1);plaque.lineTo(.94,.72);plaque.quadraticCurveTo(.94,1.17,0,1.3);plaque.quadraticCurveTo(-.94,1.17,-.94,.72);plaque.closePath();add(new T.ExtrudeGeometry(plaque,{depth:.13,bevelEnabled:true,bevelSize:.035,bevelThickness:.025,bevelSegments:4}),clay);
 add(new T.BoxGeometry(2.18,.22,.72),clay,0,-1.23,.05);add(new T.BoxGeometry(2.05,.025,.02),silver,0,-1.13,.42);
 }else if(['box','lid','pendant'].includes(props.vessel)){const radius=props.vessel==='pendant'?1.1:1.3,depth=props.vessel==='box'?.48:.1;const base=add(new T.CylinderGeometry(radius,radius,depth,96),clay);base.rotation.x=Math.PI/2;add(new T.TorusGeometry(radius-.03,.025,12,96),silver,0,0,depth/2+.02);if(props.vessel==='pendant')add(new T.TorusGeometry(.12,.027,12,48),silver,0,1.2,.02);
}else if(props.vessel==='tray'){const tray=add(new T.CylinderGeometry(1.48,1.4,.16,96),clay);tray.rotation.x=Math.PI/2;add(new T.TorusGeometry(1.43,.035,16,96),silver,0,0,.12);add(new T.TorusGeometry(1.32,.007,8,96),silver,0,0,.092)}else if(props.shape==='arch'){const outline=new T.Shape();outline.moveTo(-.42,-1.45);outline.lineTo(.42,-1.45);outline.lineTo(.42,1);outline.absarc(0,1,.42,0,Math.PI,false);outline.lineTo(-.42,-1.45);add(new T.ExtrudeGeometry(outline,{depth:.05,bevelEnabled:true,bevelSize:.02,bevelThickness:.01}),clay)}else if(props.shape==='leaf'){const leaf=new T.Shape();leaf.moveTo(0,-1.45);leaf.bezierCurveTo(-1.05,-.7,-.85,.85,0,1.45);leaf.bezierCurveTo(.85,.85,1.05,-.7,0,-1.45);add(new T.ExtrudeGeometry(leaf,{depth:.05,bevelEnabled:true,bevelSize:.02,bevelThickness:.01,bevelSegments:3}),clay)}else{const shape=new T.Shape();shape.moveTo(-.4,-1.45);shape.lineTo(.4,-1.45);shape.lineTo(.4,1.45);shape.lineTo(-.4,1.45);shape.closePath();add(new T.ExtrudeGeometry(shape,{depth:.05,bevelEnabled:true,bevelSize:.035,bevelThickness:.02,bevelSegments:4}),clay);add(new T.TorusGeometry(.055,.012,12,32),silver,0,1.22,.09)}
try{const parsed=parseMotifSvg(props.svg);const size=props.vessel==='bookmark'?.73:props.vessel==='tray'?2.5:props.vessel==='incense'?2.12:props.vessel==='cup'?1.08:props.vessel==='plaque'?1.7:['box','lid','pendant'].includes(props.vessel)?2.05:1.63;for(const path of parsed.paths){for(const geo of createReliefGeometries(path,{depth:10,bevelEnabled:false,curveSegments:8})){const pos=geo.attributes.position;for(let i=0;i<pos.count;i++){let x=(pos.getX(i)-500)*size/1000,y=-(pos.getY(i)-500)*size/1000,z=pos.getZ(i)*size/1000;if(['pot','vase','cup','penholder','jar'].includes(props.vessel)){const profile=bodyProfile.filter(p=>p.x>.5).sort((a,b)=>a.y-b.y);const j=profile.findIndex(p=>p.y>=y);const low=profile[Math.max(0,j-1)]||new T.Vector2(1,y),high=profile[Math.max(0,j)]||low;const radius=Math.max(.5,low.x+(high.x-low.x)*Math.min(1,Math.max(0,(y-low.y)/(high.y-low.y||1))));const angle=x/radius;x=Math.sin(angle)*radius;z+=Math.cos(angle)*radius+.018+(exploded.value?.7:0)}else if(props.vessel==='incense'){const planarY=y;y=-.697+z;z=-planarY}else z+=props.vessel==='plaque'?.17:props.vessel==='tray'?.13:props.vessel==='box'?.27:['lid','pendant'].includes(props.vessel)?.08:.085;pos.setXYZ(i,x,y,z)}geo.computeVertexNormals();const finalPositions=new Float32Array(pos.array);const flatPositions=new Float32Array(finalPositions.length);for(let j=0;j<pos.count;j++){flatPositions[j*3]=pos.getX(j);flatPositions[j*3+1]=pos.getY(j);flatPositions[j*3+2]=1.8+pos.getZ(j)*.01}const mesh=add(geo,silver);mesh.userData.finalPositions=finalPositions;mesh.userData.flatPositions=flatPositions;objects.push(mesh)}}}catch(error){console.error('[motif] 浮雕网格生成失败，已保留二维预览',error);const texture=new T.TextureLoader().load('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(props.svg));add(new T.PlaneGeometry(1.5,1.5),new T.MeshStandardMaterial({map:texture,transparent:true}),0,0,1.07)}
if(['faceted','fluted','waist'].includes(props.shape||'')){group.traverse(o=>{if(!(o instanceof T.Mesh)||!o.geometry?.attributes.position)return;const pos=o.geometry.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),y=pos.getY(i),z=pos.getZ(i);const a=Math.atan2(z,x);const factor=props.shape==='waist'?(.78+.22*Math.min(1,y*y)):props.shape==='fluted'?(1+.055*Math.cos(a*12)):(Math.cos(Math.PI/6)/Math.cos((a+Math.PI*2)%(Math.PI/3)-Math.PI/6));pos.setXYZ(i,x*factor,y,z*factor)}pos.needsUpdate=true;o.geometry.computeVertexNormals()})}
if(props.shape==='slender')group.scale.set(.8,1.2,.8);if(props.shape==='round')group.scale.set(1.15,.85,1.15);applyFormation();group.rotation.y=props.hero?-.26:-.12;group.rotation.x=props.vessel==='tray'?-.12:0;if(camera&&controls){camera.position.set(0,props.vessel==='incense'?2.9:.65,6.4);controls.target.set(0,0,0);controls.update()}}
function applyFormation(){for(const object of objects){const m=object as T.Mesh;const a=m.userData.flatPositions,b=m.userData.finalPositions;if(!a||!b)continue;const pos=m.geometry.attributes.position;for(let i=0;i<pos.array.length;i++)(pos.array as Float32Array)[i]=a[i]+(b[i]-a[i])*props.formation;pos.needsUpdate=true;m.geometry.computeVertexNormals()}}
watch(()=>props.formation,applyFormation);
watch(finish,v=>storePreference('xiyu-finish',v));watch(material,v=>storePreference('xiyu-material',v));
function toggleRotation(){if(reduced)return;rotate.value=!rotate.value;storePreference('xiyu-auto-rotate',rotate.value?'rotating':'paused')}
function pauseForInteraction(){interacting.value=true;resuming.value=false;clearTimeout(resumeTimer)}
function resumeAfterInteraction(){interacting.value=false;resuming.value=true;clearTimeout(resumeTimer);resumeTimer=setTimeout(()=>resuming.value=false,1500)}
function view(direction:string){if(!camera||!controls)return;rotate.value=false;const distance=camera.position.distanceTo(controls.target);const vector=direction==='front'?new T.Vector3(0,0,1):direction==='side'?new T.Vector3(1,0,0):direction==='top'?new T.Vector3(0,1,.001):direction==='macro'?new T.Vector3(.22,.15,.62):new T.Vector3(1,.5,1);const scale=direction==='macro'?0.62:1;camera.position.copy(controls.target).add(vector.normalize().multiplyScalar(distance*scale));controls.update()}
async function capture(){view('front');await new Promise(requestAnimationFrame);renderer.render(scene,camera);return renderer.domElement.toDataURL('image/png')}
defineExpose({capture});
function reset(){if(!group||!camera||!controls)return;const box=new T.Box3().setFromObject(group);const sphere=box.getBoundingSphere(new T.Sphere());const fov=camera.fov*Math.PI/180;const distance=sphere.radius/Math.sin(Math.min(fov/2,Math.atan(Math.tan(fov/2)*camera.aspect)))*1.2;controls.minDistance=Math.max(.2,sphere.radius*.8);controls.maxDistance=distance*4;controls.target.copy(sphere.center);camera.position.copy(sphere.center).add(new T.Vector3(0,.18,1).normalize().multiplyScalar(distance));controls.update()}function zoom(v:number){camera.position.multiplyScalar(v);camera.position.clampLength(3.8,10);controls.update()}
onMounted(()=>{try{scene=new T.Scene();camera=new T.PerspectiveCamera(33,1,.1,100);camera.position.set(0,.65,6.4);renderer=new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;host.value!.appendChild(renderer.domElement);const pmrem=new T.PMREMGenerator(renderer);const room=new RoomEnvironment();environment=pmrem.fromScene(room,.04).texture;scene.environment=environment;room.dispose();pmrem.dispose();scene.add(new T.HemisphereLight(0xdbebe5,0x443b30,1));const key=new T.DirectionalLight(0xffe0ba,4);key.position.set(-3,5,4);key.castShadow=true;key.shadow.mapSize.set(1024,1024);scene.add(key);const rim=new T.DirectionalLight(0xbad8da,3);rim.position.set(3,2,-2);scene.add(rim);const floor=new T.Mesh(new T.PlaneGeometry(200,200),new T.ShadowMaterial({opacity:.22}));floor.rotation.x=-Math.PI/2;floor.position.y=-1.03;floor.receiveShadow=true;scene.add(floor);controls=new OrbitControls(camera,renderer.domElement);controls.enablePan=false;controls.minDistance=3.8;controls.maxDistance=10;controls.enableDamping=!reduced;controls.maxPolarAngle=Math.PI*.8;controls.addEventListener('start',pauseForInteraction);controls.addEventListener('end',resumeAfterInteraction);observer=new ResizeObserver(()=>{const w=host.value!.clientWidth,h=host.value!.clientHeight;if(w&&h){renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();reset()}});observer.observe(host.value!);build();let last=performance.now();function tick(now:number){frame=requestAnimationFrame(tick);const delta=Math.min((now-last)/1000,.05);last=now;controls.autoRotate=rotate.value&&!interacting.value&&!resuming.value&&!reduced;controls.autoRotateSpeed=.35;controls.update(delta);renderer.render(scene,camera)}frame=requestAnimationFrame(tick)}catch{failed.value=true}});watch(()=>[props.svg,props.vessel,props.shape,finish.value,material.value,exploded.value],()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{build();pending=false})});onBeforeUnmount(()=>{clearTimeout(resumeTimer);cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();dispose();environment?.dispose();renderer?.dispose()});
</script>
<template>
<div class="vessel-scene" :class="{'hero-scene':hero}" :data-auto-rotating="rotate&&!interacting&&!resuming&&!reduced">
 <div class="scene-viewport">
  <div class="scene-canvas" ref="host" role="img" :aria-label="`${names[vessel]||vessel}的三维设计预览，可拖动旋转`"><div v-if="failed" class="scene-fallback" v-html="svg"></div></div>
  <div class="scene-motion-note"><span class="live-dot"></span>{{rotate&&!interacting&&!resuming&&!reduced?'缓缓环视中 · 拖动可细看':'拖动旋转 · 滚轮缩放'}}</div>
 </div>
 <div v-if="!hero" class="vessel-control-dock">
  <div class="material-group"><span class="dock-label">器身</span><div class="scene-materials"><button v-for="(label,key) in {zisha:'紫砂',ink:'墨陶',ivory:'素瓷'}" :class="{active:material===key}" @click="material=key" :title="label" :aria-label="label" :aria-pressed="material===key"><i :class="key"></i><span>{{label}}</span></button></div></div>
  <div class="scene-toolbar"><button @click="view('front')">正面</button><button @click="view('side')">侧面</button><button @click="view('top')">俯视</button><button @click="view('perspective')">透视</button><button @click="view('macro')" title="微距鉴赏锡镶浮雕">微距</button><button @click="host?.closest('.vessel-scene')?.requestFullscreen()">全屏</button><button :class="{active:rotate&&!reduced}" :disabled="reduced" @click="toggleRotation" :title="reduced?'已遵循系统减少动态效果设置':rotate?'暂停环视':'开启环视'" aria-label="自动旋转" :aria-pressed="rotate&&!reduced">{{rotate&&!reduced?'Ⅱ 暂停旋转':'▷ 自动旋转'}}</button><button @click="zoom(.85)" title="放大" aria-label="放大">＋</button><button @click="zoom(1.15)" title="缩小" aria-label="缩小">−</button><button @click="reset" title="复位视角" aria-label="复位视角">↺</button><button :class="{active:exploded}" @click="exploded=!exploded">{{exploded?'合拢器物':'拆解视图'}}</button></div>
  <div class="finish-group"><span class="dock-label">锡饰</span><div class="finish-switch"><button v-for="(label,key) in {brushed:'素锡',polished:'亮锡',gold:'暖金'}" :class="{active:finish===key}" :aria-pressed="finish===key" @click="finish=key">{{label}}</button></div></div>
  <button class="craft-info-button" @click="hotspot=hotspot?'':'威海锡镶数字孪生：实时演算 0.8mm 锻打素锡、镜面亮锡与鎏金暖锡在紫砂、墨陶、素瓷胎体上的浅浮雕光影层次，并同步耦合 1:1 毫米级 DXF 闭合制版轮廓。'" :aria-expanded="!!hotspot" aria-label="了解锡纹工艺">锡纹工艺 {{hotspot?'−':'＋'}}</button>
 </div>
 <div v-if="exploded&&!hero" class="exploded-callouts" aria-label="三维锡镶结构解剖说明">
  <span><b>01 · 器盖/口沿包锡环</b>承袭威海锡镶传统加固与装饰合一工艺</span>
  <span><b>02 · 0.8mm 浅浮雕锡纹层</b>经曲面法线映射精准贴合器腹弧度</span>
  <span><b>03 · 温润胎体基座</b>紫砂/墨陶/素瓷与银白金属形成虚实光影对话</span>
 </div>
 <p v-if="hotspot&&!hero" class="hotspot-note">{{hotspot}}</p>
 <div v-if="hero" class="hero-scene-hint"><span>按住器物，转动时光</span><button :disabled="reduced" @click="toggleRotation">{{rotate?'暂停环视':'开启环视'}} ↗</button></div>
</div>
</template>
<style scoped>
.vessel-scene.vessel-scene{position:relative;display:flex;flex-direction:column;flex:1;min-height:0;height:100%;width:100%;margin:0;}
.vessel-scene .scene-viewport{position:relative;flex:1;min-height:300px;height:100%;min-width:0;isolation:isolate;overflow:hidden;background:radial-gradient(ellipse at 48% 52%,color-mix(in srgb, var(--bg-elevated) 16.9%, transparent),transparent 68%),linear-gradient(130deg,var(--bg-elevated),var(--bg-elevated) 68%);}
.vessel-scene .scene-viewport:before,.vessel-scene .scene-viewport:after{content:'';position:absolute;width:78%;aspect-ratio:1;left:11%;top:50%;transform:translateY(-50%);border:1px solid color-mix(in srgb, var(--border-default) 13.3%, transparent);border-radius:50%;pointer-events:none;z-index:-1;}
.vessel-scene .scene-viewport:after{width:64%;left:18%;border-style:dashed;border-color:color-mix(in srgb, var(--border-default) 8.2%, transparent);}
.vessel-scene .scene-canvas{position:relative;inset:auto;height:100%;width:100%;cursor:grab;animation:clay-reveal .65s ease both;}.vessel-scene .scene-canvas:active{cursor:grabbing;}.vessel-scene .scene-canvas :deep(canvas){position:static;display:block;max-width:100%;touch-action:none;}
.vessel-scene .scene-motion-note{position:absolute;top:15px;left:18px;display:flex;align-items:center;gap:8px;color:var(--text-secondary);font-size:11px;letter-spacing:.5px;pointer-events:none;}.vessel-scene .live-dot{position:static;width:5px;height:5px;border-radius:50%;background:var(--bg-elevated);box-shadow:0 0 0 4px #59677310;}
.vessel-scene .vessel-control-dock{position:static;display:flex;align-items:center;justify-content:space-between;flex-wrap:nowrap;gap:6px 10px;padding:6px 12px;background:var(--bg-elevated);border-top:1px solid var(--border-default);min-width:0;overflow-x:auto;scrollbar-width:none;flex-shrink:0;}
.vessel-scene .vessel-control-dock::-webkit-scrollbar{display:none;}
.vessel-scene .material-group,.vessel-scene .finish-group{display:flex;align-items:center;gap:5px;min-width:0;flex-shrink:0;}
.vessel-scene .dock-label{color:var(--text-secondary);font-size:11px;letter-spacing:0.5px;white-space:nowrap;}
.vessel-scene .scene-materials{position:static;inset:auto;display:flex;flex-direction:row;gap:3px;flex-shrink:0;}
.vessel-scene .scene-materials button{display:flex;align-items:center;gap:4px;width:auto;height:28px;padding:2px 7px;border:1px solid var(--border-default);border-radius:4px;background:var(--bg-elevated);color:var(--text-primary);font-size:11px;}
.vessel-scene .scene-materials button.active{background:var(--bg-active);border-color:var(--accent-gold);color:var(--accent-gold-bright);}
.vessel-scene .scene-materials button:hover{background:var(--bg-elevated);border-color:var(--border-default);}
.vessel-scene .scene-materials i{width:9px;height:9px;border:1px solid var(--border-default);border-radius:50%;flex:none;}
.vessel-scene .scene-materials span{font-size:11px;line-height:1;}
.vessel-scene .scene-toolbar{position:static;inset:auto;transform:none;display:flex;align-items:center;gap:2px;padding:2px;background:var(--bg-elevated);border:1px solid var(--border-default);border-radius:5px;box-shadow:none;flex-shrink:0;}
.vessel-scene .scene-toolbar button{min-width:28px;min-height:28px;padding:2px 6px;color:var(--text-primary);font-size:12px;background:transparent;border:1px solid transparent;border-radius:3px;cursor:pointer;}
.vessel-scene .scene-toolbar button:last-child{font-size:11px;padding:2px 7px;letter-spacing:0;}
.vessel-scene .finish-switch{position:static;inset:auto;transform:none;display:flex;gap:2px;background:var(--bg-elevated);border:1px solid var(--border-default);padding:2px;border-radius:5px;flex-shrink:0;}
.vessel-scene .finish-switch button{color:var(--text-primary);font-size:11px;padding:2px 6px;border:1px solid transparent;border-radius:3px;min-height:28px;cursor:pointer;}
.vessel-scene .craft-info-button{position:static;display:inline-flex;align-items:center;gap:4px;color:var(--accent-gold);border:1px solid rgba(212,175,106,0.3);border-radius:4px;padding:2px 8px;background:rgba(212,175,106,0.06);font-size:11px;letter-spacing:.5px;min-height:28px;cursor:pointer;flex-shrink:0;white-space:nowrap;}
.vessel-scene .craft-info-button:hover{background:rgba(212,175,106,0.14);border-color:var(--accent-gold);}
.vessel-scene .hotspot-note{position:static;inset:auto;width:auto;margin:0;padding:16px 22px;background:var(--bg-elevated);color:var(--text-primary);border:0;border-top:1px solid var(--border-default);font-size:13px;line-height:1.9;box-shadow:none;}
.vessel-scene .exploded-callouts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:12px 18px;background:rgba(212,175,106,0.06);border-top:1px solid var(--border-default);font-size:11px;color:var(--text-secondary);}
.vessel-scene .exploded-callouts b{display:block;color:var(--accent-gold);margin-bottom:2px;font-size:12px;}
.vessel-scene button{transition:background .2s,border-color .2s,color .2s;}.vessel-scene button:focus-visible{outline:2px solid var(--accent-gold);outline-offset:3px;}
.vessel-scene.hero-scene .scene-viewport{height:100%;}.vessel-scene.hero-scene{height:100%;}.vessel-scene .hero-scene-hint{position:static;padding:12px;display:flex;justify-content:center;gap:20px;background:var(--bg-elevated);color:var(--text-secondary);}
@keyframes clay-reveal{from{opacity:.25;filter:brightness(.8)}to{opacity:1;filter:brightness(1)}}
@media(max-width:600px){.vessel-scene .scene-viewport{height:340px;}.vessel-scene .vessel-control-dock{padding:14px 10px;gap:12px;}.vessel-scene .scene-motion-note{left:14px;top:13px;font-size:10px;}.vessel-scene .scene-materials button{padding:6px 8px;}.vessel-scene .dock-label{font-size:10px;}.vessel-scene .hotspot-note{padding:15px;font-size:12px;}}
@media(prefers-reduced-motion:reduce){.vessel-scene .scene-canvas{animation:none;}.vessel-scene button{transition:none;}}
</style>
